-- Disposable fixtures only; the runner uses an isolated in-memory PostgreSQL.
begin;
create function pg_temp.ok(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'ASSERT: %',message;end if;end;$$;
create function pg_temp.rejected(command text) returns void language plpgsql as $$begin
 begin execute command;exception when insufficient_privilege or check_violation or raise_exception then return;end;
 raise exception 'Expected rejection: %',command;
end;$$;
insert into auth.users select ('20000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,10)n;
insert into public.void_community_profiles(user_id,username,display_name,visibility) select id,'social_'||right(id::text,4),'Pessoa '||right(id::text,2),case when right(id::text,1)='6' then 'private' else 'public' end from auth.users where id::text like '20000000%';
insert into public.void_friendships(sender,recipient,status) values('20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','accepted'),('20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000010','pending');
insert into public.follows(follower_id,followed_id) values('20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004'),('20000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000007'),('20000000-0000-4000-8000-000000000007','20000000-0000-4000-8000-000000000002');
insert into public.user_blocks(blocker_id,blocked_id) values('20000000-0000-4000-8000-000000000005','20000000-0000-4000-8000-000000000001');
insert into public.void_records(user_id,kind,item_key,payload) select id,'review','filmes:10','{"nota":4,"public":true,"item":{"id":"10","categoria":"filmes","titulo":"Favorito público","generos":["Drama"]}}'::jsonb from auth.users where id in('20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000008','20000000-0000-4000-8000-000000000006');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select pg_temp.rejected($q$select void_private.social_lock_contacts(array[auth.uid()])$q$);
select set_config('test.list',public.void_list_write_v3(null,'{"title":"Nosso grupo","description":"Privada","visibility":"private","ranked":false,"collaboration_enabled":true}',null,null)::text,true);
select public.void_list_invitation(current_setting('test.list')::uuid,'20000000-0000-4000-8000-000000000002','invite');
select pg_temp.ok(jsonb_array_length(public.void_social_people(current_setting('test.list')::uuid))=1,'friends automatically loaded, follower and pending excluded');
select pg_temp.ok(public.void_social_people(current_setting('test.list')::uuid)->0->>'status'='pending','pending invite state');
select pg_temp.ok(jsonb_array_length(public.void_social_people(current_setting('test.list')::uuid,'search','social_0003'))=1,'nonfriend nickname');
select pg_temp.ok(jsonb_array_length(public.void_social_people(current_setting('test.list')::uuid,'search','social_0005'))=0,'reverse blocker excluded');
select set_config('test.oldtoken',public.void_list_link(current_setting('test.list')::uuid)->>'token',true);
select pg_temp.ok(length(current_setting('test.oldtoken'))=64,'secure random link');
select pg_temp.rejected($q$insert into public.list_invite_links(list_id,token) values(gen_random_uuid(),repeat('a',64))$q$);
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000003',true);
select pg_temp.rejected($q$select public.void_list_invitation(current_setting('test.list')::uuid,'20000000-0000-4000-8000-000000000002','accept')$q$);
select pg_temp.ok(public.void_list_detail(current_setting('test.list')::uuid) is null,'nominal invite belongs to recipient');
select pg_temp.ok((select count(*)=0 from public.list_invite_links),'other user cannot read tokens');
select pg_temp.rejected($q$select public.void_list_link(current_setting('test.list')::uuid,'rotate')$q$);
select pg_temp.ok(public.void_list_join_link(current_setting('test.oldtoken'))->>'title'='Nosso grupo','signed-in link preview');
select pg_temp.ok(public.void_list_detail(current_setting('test.list')::uuid) is null,'preview does not grant membership');
select pg_temp.ok((public.void_list_join_link(current_setting('test.oldtoken'),true)->>'joined')::boolean,'join via token');
select public.void_list_join_link(current_setting('test.oldtoken'),true);
select pg_temp.ok((select count(*)=1 from public.list_members where list_id=current_setting('test.list')::uuid and user_id=auth.uid()),'join idempotent');
select pg_temp.ok(public.void_list_detail(current_setting('test.list')::uuid)->>'title'='Nosso grupo','accepted access persists in table');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
select public.void_list_invitation(current_setting('test.list')::uuid,'20000000-0000-4000-8000-000000000003','remove');
select set_config('test.token',public.void_list_link(current_setting('test.list')::uuid,'rotate')->>'token',true);
select pg_temp.ok(current_setting('test.token')<>current_setting('test.oldtoken'),'rotation new random token');
select pg_temp.rejected($q$select public.void_list_join_link(current_setting('test.oldtoken'),true)$q$);
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000003',true);
select pg_temp.rejected($q$select public.void_list_join_link(current_setting('test.token'),true)$q$);
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000005',true);
select pg_temp.rejected($q$select public.void_list_join_link(current_setting('test.token'),true)$q$);
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
select public.void_list_link(current_setting('test.list')::uuid,'disable');
select pg_temp.rejected($q$select public.void_list_join_link(current_setting('test.token'),true)$q$);
select pg_temp.ok(public.void_list_link(current_setting('test.list')::uuid)->>'enabled'='false','get does not reenable disabled link');
select public.void_list_link(current_setting('test.list')::uuid,'rotate');
update public.lists set collaboration_enabled=false where id=current_setting('test.list')::uuid;
update public.lists set collaboration_enabled=true where id=current_setting('test.list')::uuid;
select pg_temp.ok(public.void_list_link(current_setting('test.list')::uuid)->>'enabled'='false','disabling collaboration revokes link');

-- All four media types retain independent canonical identities. Repeated sends
-- never change a message, recreate notifications, or write any review.
do $$declare media text;result jsonb;begin
 foreach media in array array['filmes','series','jogos','animes'] loop
  result:=public.void_recommend_work(jsonb_build_object('media_type',media,'external_id','90','snapshot',jsonb_build_object('titulo','Mesmo título','poster','','ano','2026')),array['20000000-0000-4000-8000-000000000002'::uuid],'Vai gostar!');
  perform pg_temp.ok(result->>'sent'='1','recommend each category');
 end loop;
end;$$;
select pg_temp.ok(public.void_recommend_work('{"media_type":"jogos","external_id":"90","snapshot":{"titulo":"Outro texto"}}',array['20000000-0000-4000-8000-000000000002'::uuid],'Duplicado')->>'sent'='0','dedup actor recipient media ID');
select pg_temp.rejected($q$select public.void_recommend_work('{"media_type":"jogos","external_id":"90","snapshot":{"titulo":"Obra"}}',array[auth.uid()])$q$);
select pg_temp.rejected($q$select public.void_recommend_work('{"media_type":"jogos","external_id":"90","snapshot":{"titulo":"Obra"}}',array['20000000-0000-4000-8000-000000000003'::uuid])$q$);
select pg_temp.rejected($q$select public.void_recommend_work('{"media_type":"jogos","external_id":"90","snapshot":{"titulo":"Obra"}}',array['20000000-0000-4000-8000-000000000005'::uuid])$q$);
select pg_temp.rejected($q$select public.void_recommend_work('{"media_type":"livros","external_id":"90","snapshot":{"titulo":"Obra"}}',array['20000000-0000-4000-8000-000000000002'::uuid])$q$);
select pg_temp.rejected($q$insert into public.work_recommendations(sender_id,recipient_id,media_type,external_id,snapshot) values(auth.uid(),'20000000-0000-4000-8000-000000000003','jogos','5','{}')$q$);
select pg_temp.ok(jsonb_array_length(public.void_work_recommendations('jogos','90'))=0,'sender cannot see received indicator');
select set_config('test.suggestions',public.void_social_suggestions()::text,true);
select pg_temp.ok(current_setting('test.suggestions')::jsonb->0->>'user_id'='20000000-0000-4000-8000-000000000007','public mutual connections ranked first');
select pg_temp.ok(current_setting('test.suggestions')::jsonb->1->>'user_id'='20000000-0000-4000-8000-000000000008','public taste overlap ranked second');
select pg_temp.ok(not exists(select 1 from jsonb_array_elements(current_setting('test.suggestions')::jsonb)p where p->>'user_id' in('20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000004','20000000-0000-4000-8000-000000000005','20000000-0000-4000-8000-000000000006','20000000-0000-4000-8000-000000000010')),'suggestions exclude self friend followed blocked private pending');
select pg_temp.ok(jsonb_array_length(public.void_social_suggestions())=0,'durable cooldown across calls');
select public.void_social_suggestions('20000000-0000-4000-8000-000000000008');
reset role;
select pg_temp.ok((select count(*)=4 from public.work_recommendations),'no duplicate rows');
select pg_temp.ok((select count(*)=4 from public.notifications where type='work_recommendation'),'exactly one real notification per recommendation');
select pg_temp.ok((select count(*)=3 from public.void_records),'no automatic reviews or rating changes');
select pg_temp.ok((select bool_and(message='Vai gostar!') from public.work_recommendations),'duplicate does not replace message');
update public.social_suggestion_history set shown_at=now()-interval '4 days';
set local role authenticated;
select pg_temp.ok(not exists(select 1 from jsonb_array_elements(public.void_social_suggestions())p where p->>'user_id'='20000000-0000-4000-8000-000000000008'),'dismiss survives cooldown');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select pg_temp.ok(jsonb_array_length(public.void_work_recommendations('jogos','90'))=1,'correct media received indicator');
select pg_temp.ok(public.void_work_recommendations('jogos','90')->0->>'message'='Vai gostar!','received message persisted');
select pg_temp.ok(jsonb_array_length(public.void_work_recommendations('jogos','91'))=0,'different work never mixed');
select pg_temp.ok((select count(*)=4 from public.notifications where type='work_recommendation' and read_at is null),'recipient unread notifications');
select pg_temp.ok((select count(*)=0 from public.social_suggestion_history),'another account cannot read suggestion history');
insert into public.notification_preferences(user_id,work_recommendation) values(auth.uid(),false);
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
select public.void_recommend_work('{"media_type":"jogos","external_id":"92","snapshot":{"titulo":"Obra"}}',array['20000000-0000-4000-8000-000000000002'::uuid]);
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000003',true);
select pg_temp.ok((select count(*)=0 from public.work_recommendations),'third account cannot read recommendations');
select pg_temp.ok((select count(*)=0 from public.notifications where type='work_recommendation'),'third account cannot read recommendation notifications');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select pg_temp.ok((select count(*)=4 from public.notifications where type='work_recommendation'),'notification opt-out respected');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
select set_config('test.blocklist',public.void_list_write_v3(null,'{"title":"Proteção de contato","visibility":"private","ranked":false,"collaboration_enabled":true}',null,null)::text,true);
select set_config('test.blocktoken',public.void_list_link(current_setting('test.blocklist')::uuid)->>'token',true);
select public.void_list_invitation(current_setting('test.blocklist')::uuid,'20000000-0000-4000-8000-000000000002','invite');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select public.void_list_invitation(current_setting('test.blocklist')::uuid,auth.uid(),'accept');
select pg_temp.ok(public.void_list_detail(current_setting('test.blocklist')::uuid)->>'title'='Proteção de contato','member before blocking');
insert into public.user_blocks(blocker_id,blocked_id) values(auth.uid(),'20000000-0000-4000-8000-000000000001');
select pg_temp.ok(public.void_list_detail(current_setting('test.blocklist')::uuid) is null,'block revokes membership');
select pg_temp.rejected($q$select public.void_list_join_link(current_setting('test.blocktoken'),true)$q$);
select pg_temp.ok((select count(*)=0 from public.work_recommendations),'block revokes old recommendations');
select pg_temp.ok((select count(*)=0 from public.notifications where type='work_recommendation'),'block revokes notification visibility');
select pg_temp.rejected($q$select public.void_list_invitation(current_setting('test.list')::uuid,auth.uid(),'accept')$q$);
delete from public.user_blocks where blocker_id=auth.uid();
select pg_temp.ok((select count(*)=0 from public.work_recommendations),'unblock does not recreate friendship');
select pg_temp.rejected($q$select public.void_list_join_link(current_setting('test.blocktoken'),true)$q$);
select pg_temp.ok(public.void_list_detail(current_setting('test.blocklist')::uuid) is null,'unblock does not restore list membership');
set local role anon;
select pg_temp.rejected($q$select public.void_list_join_link(current_setting('test.token'),true)$q$);
select pg_temp.rejected($q$select public.void_work_recommendations('jogos','90')$q$);
select pg_temp.rejected($q$select * from public.user_blocks$q$);
reset role;
rollback;
